#define SHADER_NAME PHASER_MULTI_FS
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uMainSampler[16];
varying vec2 outTexCoord;
varying float outTexId;
varying float outTintEffect;
varying vec4 outTint;
void main ()
{
    vec4 texture;
    if (outTexId < 0.5)
	{
		texture = texture2D(uMainSampler[0], outTexCoord);
	}
	else if (outTexId < 1.5)
	{
		texture = texture2D(uMainSampler[1], outTexCoord);
	}
	else if (outTexId < 2.5)
	{
		texture = texture2D(uMainSampler[2], outTexCoord);
	}
	else if (outTexId < 3.5)
	{
		texture = texture2D(uMainSampler[3], outTexCoord);
	}
	else if (outTexId < 4.5)
	{
		texture = texture2D(uMainSampler[4], outTexCoord);
	}
	else if (outTexId < 5.5)
	{
		texture = texture2D(uMainSampler[5], outTexCoord);
	}
	else if (outTexId < 6.5)
	{
		texture = texture2D(uMainSampler[6], outTexCoord);
	}
	else if (outTexId < 7.5)
	{
		texture = texture2D(uMainSampler[7], outTexCoord);
	}
	else if (outTexId < 8.5)
	{
		texture = texture2D(uMainSampler[8], outTexCoord);
	}
	else if (outTexId < 9.5)
	{
		texture = texture2D(uMainSampler[9], outTexCoord);
	}
	else if (outTexId < 10.5)
	{
		texture = texture2D(uMainSampler[10], outTexCoord);
	}
	else if (outTexId < 11.5)
	{
		texture = texture2D(uMainSampler[11], outTexCoord);
	}
	else if (outTexId < 12.5)
	{
		texture = texture2D(uMainSampler[12], outTexCoord);
	}
	else if (outTexId < 13.5)
	{
		texture = texture2D(uMainSampler[13], outTexCoord);
	}
	else if (outTexId < 14.5)
	{
		texture = texture2D(uMainSampler[14], outTexCoord);
	}
	else 
	{
		texture = texture2D(uMainSampler[15], outTexCoord);
	}
    vec4 texel = vec4(outTint.bgr * outTint.a, outTint.a);
    vec4 color = texture * texel;
    if (outTintEffect == 1.0)
    {
        color.rgb = mix(texture.rgb, outTint.bgr * outTint.a, texture.a);
    }
    else if (outTintEffect == 2.0)
    {
        color = texel;
    }
    gl_FragColor = color;
}

#define SHADER_NAME PHASER_BITMAP_MASK_VS
